'use strict';

// These strings were authored by Telegram bridge/runtime code and were once
// embedded in a rendered provider request. They are control-plane data, never
// evidence that a participant said, requested, or believed anything.
const LEGACY_GROUP_PROMPT_FINGERPRINTS = Object.freeze([
  '漏掉的消息只是环境音，不是欠债',
  '不要把整个群当成她',
  '群聊安全约定：本请求没有本地文件',
  '只输出严格 JSON',
  'replyToMessageId 只能来自这里的 messageId',
  'TG_GROUP_BATCH_V1',
  'TARGET_JSONL',
  '[Tether Telegram group response contract]',
]);

// These are phrases generated by the old fold/card pipeline after it had
// already misclassified the bridge wrapper as owner-authored conversation.
// They are scoped to derived memory sanitation; raw append-only transcripts
// are deliberately preserved unchanged for audit and migration.
const DERIVED_CONTROL_ATTRIBUTION_FINGERPRINTS = Object.freeze([
  '群聊边界指令',
  '群聊边界长期指令',
  '私聊全量记录',
  '私聊须全量记录',
  '群聊为环境音',
  '注意义务等级',
  '信息义务',
  '不应把群聊等同',
  '不得将群聊等同',
  '未接的消息不算欠债',
  '群聊未接消息不算欠债',
]);

const DERIVED_FOLLOWUP_FINGERPRINTS = Object.freeze([
  '该分级原则',
  '分级原则已稳定',
  '该指令与此前',
  '该指令与既有',
  '该指令确立',
  '此为稳定长期指令',
  '首次收到该界定',
  '再次重申强化',
  '本轮再次重申',
  '仍为长期指令',
  '重申而非新增',
]);

const FALSE_SECTION_HEADING = /^(?:#{1,6}\s*)?.*(?:群聊边界|私聊与群聊.*义务|长期指令).*$/u;

function includesAny(value, fingerprints) {
  const text = String(value || '');
  return fingerprints.some((fingerprint) => text.includes(fingerprint));
}

function containsLegacyGroupPrompt(value) {
  return includesAny(value, LEGACY_GROUP_PROMPT_FINGERPRINTS);
}

function containsControlPlaneArtifact(value) {
  return includesAny(value, [
    ...LEGACY_GROUP_PROMPT_FINGERPRINTS,
    ...DERIVED_CONTROL_ATTRIBUTION_FINGERPRINTS,
  ]);
}

function parseLegacyTelegramGroupPrompt(value) {
  const text = String(value || '');
  if (!containsLegacyGroupPrompt(text)) return [];
  const messages = [];
  for (const line of text.split(/\r?\n/u)) {
    const candidate = line.trim();
    if (!candidate.startsWith('{') || !candidate.endsWith('}')) continue;
    let parsed;
    try { parsed = JSON.parse(candidate); } catch (_) { continue; }
    if (
      !parsed
      || typeof parsed !== 'object'
      || Array.isArray(parsed)
      || parsed.messageId == null
      || parsed.sentAt == null
      || parsed.sender == null
      || !Object.hasOwn(parsed, 'text')
    ) continue;
    messages.push({
      messageId: String(parsed.messageId),
      sentAt: String(parsed.sentAt),
      senderId: parsed.senderId == null ? null : String(parsed.senderId),
      senderDisplayName: String(parsed.sender),
      senderUsername: parsed.username == null ? null : String(parsed.username),
      senderIsBot: parsed.senderIsBot === true,
      replyToMessageId: parsed.replyToMessageId == null
        ? null
        : String(parsed.replyToMessageId),
      replyTargetAvailable: parsed.replyToMessageId != null,
      text: String(parsed.text || ''),
      attachmentRefs: [],
      evidenceClass: 'conversation',
      legacyRecovered: true,
    });
  }
  return messages;
}

function contaminatedSentence(value, contaminatedLine = false) {
  const text = String(value || '');
  if (containsControlPlaneArtifact(text)) return true;
  return contaminatedLine && includesAny(text, DERIVED_FOLLOWUP_FINGERPRINTS);
}

function sanitizeContaminatedLine(value) {
  const line = String(value || '');
  const contaminated = containsControlPlaneArtifact(line);
  if (!contaminated) return line;
  // A list item carrying the false instruction is one atomic memory claim.
  // Removing the entire item is safer than retaining a dangling paraphrase.
  if (/^\s*[-*+]\s+/u.test(line)) return '';
  const pieces = line.match(/[^\u3002！？!?]+[\u3002！？!?]?/gu) || [line];
  return pieces
    .filter((piece) => !contaminatedSentence(piece, true))
    .join('')
    .trim();
}

function sanitizeDerivedMemoryText(value) {
  const original = String(value || '').replace(/\r\n?/gu, '\n').trim();
  if (!original || !containsControlPlaneArtifact(original)) return original;
  const sections = original.split(/(?=^#{1,6}\s+)/gmu);
  const cleanedSections = [];
  for (const section of sections) {
    const lines = section.split('\n');
    const heading = lines[0] || '';
    if (FALSE_SECTION_HEADING.test(heading) && containsControlPlaneArtifact(section)) continue;
    const cleanedLines = lines.map(sanitizeContaminatedLine);
    const cleaned = cleanedLines.join('\n')
      .replace(/\n{3,}/gu, '\n\n')
      .replace(/^\s*---\s*$(?:\n\s*---\s*$)+/gmu, '---')
      .trim();
    if (cleaned && !containsControlPlaneArtifact(cleaned)) cleanedSections.push(cleaned);
  }
  return cleanedSections.join('\n\n').replace(/\n{3,}/gu, '\n\n').trim();
}

function assertNoControlPlaneArtifact(value, label = 'memory candidate') {
  if (!containsControlPlaneArtifact(value)) return;
  const error = new Error(`${label} 含有控制层文本，拒绝写入记忆`);
  error.code = 'MEMORY_CONTROL_PLANE_CONTAMINATION';
  throw error;
}

module.exports = {
  DERIVED_CONTROL_ATTRIBUTION_FINGERPRINTS,
  LEGACY_GROUP_PROMPT_FINGERPRINTS,
  assertNoControlPlaneArtifact,
  containsControlPlaneArtifact,
  containsLegacyGroupPrompt,
  parseLegacyTelegramGroupPrompt,
  sanitizeDerivedMemoryText,
};
